<?php
namespace Tests\Feature;use App\Models\{Institution,Survey,User};use Database\Seeders\{InsightRuleSeeder,RolesAndPermissionsSeeder,SystemThresholdSeeder};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class InsightEngineTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed([RolesAndPermissionsSeeder::class,SystemThresholdSeeder::class,InsightRuleSeeder::class]);}public function test_weak_rssi_generates_explainable_coverage_insight():void{$u=User::factory()->create();$u->assignRole('Network Admin');$i=Institution::create(['name'=>'T','slug'=>'t']);$c=$i->campuses()->create(['name'=>'M','code'=>'M']);$b=$c->buildings()->create(['name'=>'B','code'=>'B']);$f=$b->floors()->create(['name'=>'G','code'=>'G','level_number'=>0]);$fp=$f->floorPlans()->create(['uploaded_by'=>$u->id,'original_name'=>'p','file_path'=>'p','mime_type'=>'image/png','file_size'=>1,'version'=>1]);$s=Survey::create(['floor_id'=>$f->id,'floor_plan_id'=>$fp->id,'created_by'=>$u->id,'name'=>'S','minimum_points'=>10]);for($n=0;$n<10;$n++){$p=$s->points()->create(['floor_plan_id'=>$fp->id,'captured_by'=>$u->id,'x_normalized'=>.05+$n*.08,'y_normalized'=>.5,'source_type'=>'measured','collection_method'=>'manual','validation_status'=>'valid','captured_at'=>now()]);$p->measurements()->create(['rssi_dbm'=>-80,'source_type'=>'measured','collection_method'=>'manual','captured_at'=>now()]);}$this->actingAs($u)->postJson("/api/surveys/{$s->id}/insights/generate")->assertCreated()->assertJsonFragment(['title'=>'Possible coverage problem','classification'=>'Possible coverage problem detected.']);$this->assertDatabaseHas('insights',['survey_id'=>$s->id,'severity'=>'high']);}}
